    .ag-filter-apply-panel-button.ag-button {
      @apply base-button;
      &[data-ref='applyFilterButton'] {
        @include button-primary;
      }

      &[data-ref='resetFilterButton'] {
        @include button-secondary;
      }
    }
  }

  @apply overflow-x-auto;
  .ag-header {
    @apply border-b border-tertiary;
    .ag-header-cell.align-right {
      .ag-header-cell-label {
        @apply justify-end;
      }
    }
    .ag-header-viewport,
    .ag-pinned-left-header {
      .ag-floating-filter {
        input {
          @include input-field;
          @apply m-0 p-0 px-2;
          height: 24px !important;
        }
      }
      // A filter row with no input (see EmptyFloatingFilter): drop the empty body so the button
      // centres in the cell instead of hanging off its right edge.
      .ag-floating-filter:has(.ag-grid-filter-button-only) {
        .ag-floating-filter-body {
          @apply hidden;
        }

        .ag-floating-filter-button {
          @apply flex h-full w-full items-center justify-center;
          margin: 0;
        }
      }
    }
  }

  .ag-cell {
    user-select: text;
    @apply flex items-center;
    &.ag-grid-no-border,
    &.ag-cell-focus {
      @apply border-0;
    }

    &.column-divider:not(:last-child) {
      @apply border-0 border-r border-solid border-tertiary;
    }

    &.align-right {
      @apply justify-end;
    }
  }
  .ag-cell.ag-cell-first-right-pinned:not(
      .ag-cell-range-left,
      .ag-cell-range-single-cell,
      .ag-cell-focus:not(.ag-cell-range-selected):focus-within
    ) {
    @apply border-0;
  }
  .ag-error-row {
    @apply bg-error;
    #editable-cell-renderer {
  // viewport breaks scroll sync and clips trailing test-case columns.
  .ag-theme-balham-dark {
    overflow-x: hidden;
  }

  .ag-header-cell.heat-map-test-case-header {
    padding-left: 0 !important;
    padding-right: 0 !important;

    .ag-header-cell-comp-wrapper {
      height: 100%;
      padding-left: 0;
      padding-right: 0;
    }
  }

  .ag-header-cell {
    border-top: none !important;
    border-left: none !important;
    @apply border-r border-b border-tertiary;
  }

  .ag-cell {
    border-top: none !important;
    border-left: none !important;
    @apply border-r border-b border-tertiary;
    padding: 0 !important;
  }

  // The kit wraps the score renderer in a dropdown trigger (`items-center`) and a
  // content-sized span. With the number hidden, that span collapses to the 1px
  // border, so the bucket color never fills the row.
  .ag-cell > .dial-kit-dropdown {
    align-items: stretch;

    > span {
      display: flex;
      height: 100%;
      min-height: 0;
    }
  }

  .ag-body-horizontal-scroll {
    min-height: 12px;
  }
}

// GridView wraps the grid in height: 100%. Auto height must follow the rows instead,
// otherwise the stability heatmap stays inside a fixed viewport and scrolls.
.heat-map-grid--auto-height {
  > .size-full {
    height: auto;
  }
}

.conversations-grid {
  .ag-header-group-cell {
    @apply border-b border-tertiary pt-1.5;
  }

  .ag-header-group-cell-label {
    @apply items-start justify-start;
  }

  .ag-header-cell {
    @apply py-1.5;
  }

  .ag-cell {
    @apply py-2;
  }
}
import { CellClassParams, ColDef } from 'ag-grid-community';

export {
  DURATION_COLUMN_WIDTH,
  EXTRACTED_COLUMN_MIN_WIDTH,
  fixedWidthColDef,
  HTTP_COLUMN_WIDTH,
  NO_FILTER_COL_DEF,
  NUMBER_FILTER_COL_DEF,
  REQUEST_INDEX_COLUMN_WIDTH,
  RUN_INDEX_COLUMN_WIDTH,
  STATUS_COLUMN_WIDTH,
  TEST_CASE_NAME_COLUMN_WIDTH,
  TEXT_FILTER_COL_DEF,
  TURN_INDEX_COLUMN_WIDTH,
} from '@/src/components/Runs/grid-column-layout';

export const COMPARE_SCORE_COLUMN_MIN_WIDTH = 80;
export const DEFAULT_COMPARE_DELTA_HEADER = 'Delta';

/**
 * Score columns (run 1, run 2, delta) take only the width they need: the grid's default `flex` and
 * size-to-fit would otherwise stretch every metric to share the leftover width.
 */
export const compareScoreColDef: Pick<ColDef, 'width' | 'minWidth' | 'flex' | 'suppressSizeToFit'> = {
  width: COMPARE_SCORE_COLUMN_MIN_WIDTH,
  minWidth: COMPARE_SCORE_COLUMN_MIN_WIDTH,
  flex: 0,
  suppressSizeToFit: true,
};

export const COMPARE_GROUP_HEADER_HEIGHT = 28;

export const EXECUTION_GROUP_HEADER = 'Execution';
export const EXECUTION_STATUS_GROUP_HEADER = 'Execution status';
export const EXTRACTED_GROUP_HEADER = 'Extracted';

export const formatCompareColumnHeader = (runIndex: string, label: string) => `[${runIndex}] ${label}`;

export const COMPARE_MISSING_DISPLAY = '—';

export const compareMissingValueCellClassRules = {
  'text-secondary': (params: CellClassParams) => params.value === COMPARE_MISSING_DISPLAY,
};

export const compareGridOptions = {
  groupHeaderHeight: COMPARE_GROUP_HEADER_HEIGHT,
  hidePaddedHeaderRows: true,
  defaultColDef: {
    cellClassRules: compareMissingValueCellClassRules,
  },
};

