  ...fixedWidthColDef(width),
  ...rightAlignedColumn,
  valueGetter: (params: ValueGetterParams<CompareAnalyticsRow>) => {
    const index = params.data && getCompareRowResult(params.data, context.run.slot)?.[field];
    return index != null ? index + 1 : '—';
  },
